// Official Project Harmony augment pack promoted from the 2026-09-18 design sheet.
// Keep this registry separate from the original 22 staged augments so their
// registry/test contract remains stable.

const card = ({
  name,
  tier,
  maxCopies,
  maxUpgrade,
  cost,
  note,
  category,
  effects,
  upgrades = null,
  acquisition = { rewardSources: ["combat"], shop: true },
}) => ({
  name,
  tier,
  maxCopies,
  maxUpgrade,
  cost,
  note,
  category,
  acquisition,
  ...effects,
  ...(upgrades ? { upgrades } : {}),
});

const item = ({
  id,
  name,
  kind,
  sheetTier,
  effect,
  value = 1,
  maxOwned = 1,
  stackable = maxOwned > 1,
  description,
  acquisition,
  price = null,
}) => ({
  id,
  name,
  kind,
  // Harmony item tiers are canonical 0-based; the design sheet is T1-T4.
  tier: Math.max(0, Math.min(3, Number(sheetTier) - 1)),
  sheetTier,
  effect,
  value,
  maxOwned,
  stackable,
  passive: true,
  image: null,
  family: effect,
  description,
  acquisition,
  ...(Number.isFinite(price) ? { price } : {}),
});

const NORMAL = Object.freeze({
  rewardSources: ["golden", "elite", "boss"],
  shop: true,
});
const RARE = Object.freeze({
  rewardSources: ["golden", "elite", "boss"],
  shop: false,
  rareOnly: true,
});
const EVENT = (eventRooms, requiresItem = null) =>
  Object.freeze({
    rewardSources: [],
    shop: false,
    eventRooms,
    ...(requiresItem ? { requiresItem } : {}),
  });

